#!/usr/bin/env bash
# zrm6.sh: zmerge6 (round-2 winners) vs zmerge5 on the RigMark + TTFT harness, two sweeps with the arm order
# reversed (m6a: base, ours; m6b: ours, base), each arm its own GPU-lock hold. FILL stays off in both arms (the fix
# is in zmerge6 but the setting changes TTFT and is the owner's call); PF1 is not in (its repeat is still being read).
set -u
M5="PREPARE=0 TF_FLASHNEXT_MTP_FP8=/root/.cache/huggingface/ots-mtp-fp8 TF_FLASHNEXT_CONFIDENCE=-0.15 TF_FLASHNEXT_NGRAM_RANDOM=1 TF_FLASHNEXT_NGRAM_THREADS=32 TF_FLASHNEXT_NGRAM_PREFETCH=1 TF_FLASHNEXT_WINDOW=64 TF_FLASHNEXT_SEQ_POOL=4 TF_FLASHNEXT_WARM_POOL=4 TF_FLASHNEXT_SOLO_MAX=1024 TF_FLASHNEXT_MULTI_LRU=1 TF_FLASHNEXT_MULTI_MAX=192 TF_FLASHNEXT_MULTI_VERIFY=1 TF_FLASHNEXT_W8_QMMF_FUSE=4 TF_FLASHNEXT_W8_QMMF_FUSE_N=2048 TF_FLASHNEXT_W8_HEAD_MT=2 TF_FLASHNEXT_UPMIX_DECODE=1 TF_FLASHNEXT_DRAFT_INT4=1 TF_FLASHNEXT_W6_TP=0.05 TF_FLASHNEXT_W6_TC=0.20 TF_FLASHNEXT_W6_CAP2=7 TENSORFOLD_COPY_RESYNC=1 TENSORFOLD_COPY_RAMP=jump TENSORFOLD_COPY_MISS=keep TENSORFOLD_COPY_RESYNC_PROMPT_ONLY=1 TF_FLASHNEXT_COPY_SHARED=1"
BASE="$M5 IMAGE=tensorfold-qwen38:zmerge5 PATCHES=zmerge5"
OURS="$M5 IMAGE=tensorfold-qwen38:zmerge6 TF_FLASHNEXT_HC_Q12=1 TF_FLASHNEXT_QSA_DECODE=12 TF_FLASHNEXT_QSA_TILE=4 TF_FLASHNEXT_FP8_TILE=1 TF_FLASHNEXT_INT4_PROMPT_GU=2 TF_FLASHNEXT_PREFILL_ROWS=4096 PATCHES=zmerge6"
RIGMARK_ID=zrm-m6 bash ~/work/bench/zab_rm.sh m6a "$BASE" "$OURS"
RIGMARK_ID=zrm-m6 ORDER="ours base" bash ~/work/bench/zab_rm.sh m6b "$BASE" "$OURS"
echo ZRM6-DONE > ~/work/bench/zrm6.done
